class JsonCache<T> {
  final Map<String, (T, DateTime)> _cache = {};
  final Duration _ttl;
  final Future<T> Function(String) _fetcher;

  JsonCache(this._fetcher, {Duration ttl = const Duration(minutes: 5)}) : _ttl = ttl;

  Future<T> get(String key) async {
    final entry = _cache[key];
    if (entry != null && DateTime.now().difference(entry.$2) < _ttl) {
      return entry.$1;
    }
    final value = await _fetcher(key);
    _cache[key] = (value, DateTime.now());
    return value;
  }
}

