class RateLimiter {
  final int _maxPerSecond;
  final _timestamps = <DateTime>[];

  RateLimiter(this._maxPerSecond);

  bool erlaubt() {
    final now = DateTime.now();
    _timestamps.removeWhere(
      (t) => now.difference(t).inSeconds >= 1
    );
    if (_timestamps.length >= _maxPerSecond) return false;
    _timestamps.add(now);
    return true;
  }
}

