typedef Middleware<S> = S Function(S state, dynamic action);

class Store<S> {
  S _state;
  final Middleware<S> _reducer;
  final _listeners = <void Function(S)>[];

  Store(this._state, this._reducer);

  S get state => _state;

  void dispatch(dynamic action) {
    _state = _reducer(_state, action);
    for (final l in _listeners) l(_state);
  }

  void subscribe(void Function(S) listener) => _listeners.add(listener);
}

