Stream<T> debounce<T>(Stream<T> stream, Duration delay) {
  StreamController<T>? controller;
  Timer? timer;
  late StreamSubscription<T> sub;
  controller = StreamController<T>(
    onListen: () {
      sub = stream.listen((event) {
        timer?.cancel();
        timer = Timer(delay, () => controller!.add(event));
      });
    },
    onCancel: () { sub.cancel(); timer?.cancel(); },
  );
  return controller.stream;
}

Stream<T> throttle<T>(Stream<T> stream, Duration interval) async* {
  var lastEmit = DateTime(0);
  await for (final event in stream) {
    final now = DateTime.now();
    if (now.difference(lastEmit) >= interval) {
      lastEmit = now;
      yield event;
    }
  }
}

