Stream<(A, B)> zip<A, B>(Stream<A> a, Stream<B> b) async* {
  final iterA = StreamIterator(a);
  final iterB = StreamIterator(b);
  while (await iterA.moveNext() && await iterB.moveNext()) {
    yield (iterA.current, iterB.current);
  }
  await iterA.cancel();
  await iterB.cancel();
}

