import 'package:custom_lint_builder/custom_lint_builder.dart';

class NoPrintRule extends DartLintRule {
  NoPrintRule() : super(code: const LintCode(
    name: 'no_print',
    problemMessage: 'Kein print() in diesem Projekt',
  ));

  @override
  void run(CustomLintContext context) {
    context.registry.addMethodInvocation((node) {
      if (node.methodName.name == 'print') {
        reportLintForNode(code, node);
      }
    });
  }
}

class TodoApp {
  final List<Todo> _todos = [];
  final TodoRepository _repo;

  TodoApp(this._repo);

  Future<void> laden() async {
    final daten = await _repo.getAll();
    _todos.addAll(daten);
  }

  void hinzufügen(String titel) {
    _todos.add(Todo(titel: titel));
  }

  List<Todo> get offene => _todos.where((t) => !t.erledigt).toList();
}

class Todo {
  final String id;
  final String titel;
  bool erledigt;
  final DateTime erstellt;

  Todo({
    required this.titel,
    this.erledigt = false,
    String? id,
    DateTime? erstellt,
  })  : id = id ?? DateTime.now().millisecondsSinceEpoch.toString(),
        erstellt = erstellt ?? DateTime.now();

  Todo copyWith({String? titel, bool? erledigt}) => Todo(
    id: id,
    titel: titel ?? this.titel,
    erledigt: erledigt ?? this.erledigt,
    erstellt: erstellt,
  );
}

class TodoCli {
  final TodoApp _app;

  TodoCli(this._app);

  Future<void> starte() async {
    await _app.laden();

    while (true) {
      _zeigeMenu();
      final wahl = stdin.readLineSync()?.trim();

      switch (wahl) {
        case '1': await _hinzufügen(); 
        case '2': _zeigeListe();
        case 'q': ___;
        default: print('Unbekannte Eingabe');
      }
    }
  }
}

abstract class TodoRepository {
  Future<List<Todo>> getAll();
  Future<void> save(Todo todo);
  Future<void> delete(String id);
}

class JsonFileTodoRepository implements TodoRepository {
  final String _pfad;
  JsonFileTodoRepository(this._pfad);

  @override
  Future<List<Todo>> getAll() async {
    final f = File(_pfad);
    if (!await f.exists()) return [];
    final json = jsonDecode(await f.readAsString()) as List;
    return json.map((j) => Todo.fromJson(j as Map<String, dynamic>)).toList();
  }

  @override
  Future<void> save(Todo todo) async {
    final todos = await getAll();
    final idx = todos.indexWhere((t) => t.id == todo.id);
    if (idx >= 0) todos[idx] = todo; else todos.add(todo);
    await File(_pfad).writeAsString(jsonEncode(todos.map((t) => t.toJson()).toList()));
  }
}

void main(List<String> args) async {
  final repo = JsonFileTodoRepository('todos.json');
  final app = TodoApp(repo);
  final cli = TodoCli(app);

  try {
    await cli.starte();
  } catch (e, st) {
    stderr.writeln('Fehler: $e');
    stderr.writeln(st);
    exit(1);
  }
}

