extension TodoListExtension on List<Todo> {
  List<Todo> get erledigt => where((t) => t.erledigt).toList();
  List<Todo> get offen => where((t) => !t.erledigt).toList();
  List<Todo> sortedByDatum() => [...this]..sort((a, b) => a.erstellt.compareTo(b.erstellt));
  int get erledigungsquote => isEmpty ? 0 : (erledigt.length / length * 100).round();
}

